```php
class ReindexElasticsearch extends Command
{
    protected $signature = 'es:reindex {--fresh : Delete existing index first}';
    protected $description = 'Reindex all jobs from MySQL to Elasticsearch';

    public function __construct(
        private readonly Client $esClient,
        private readonly JobRepositoryInterface $jobRepository
    ) {
        parent::__construct();
    }

    public function handle(): int
    {
        $alias = config('elasticsearch.index'); // 'jobs'
        $newIndex = $alias . '_v' . time();

        $this->info("Creating new index: {$newIndex}");
        $this->createIndex($newIndex);

        $this->info('Indexing jobs from MySQL...');
        $this->indexAllJobs($newIndex);

        $this->info('Switching alias...');
        $this->switchAlias($alias, $newIndex);

        $this->info('Cleaning up old indexes...');
        $this->cleanupOldIndexes($alias, $newIndex);

        $this->info('Reindex complete!');
        return Command::SUCCESS;
    }

    private function createIndex(string $indexName): void
    {
        $this->esClient->indices()->create([
            'index' => $indexName,
            'body' => [
                'mappings' => [...] // same mapping as indexer
            ],
        ]);
    }

    private function indexAllJobs(string $indexName): void
    {
        $bar = $this->output->createProgressBar();
        $bar->start();

        Job::with('company:id,name,industry')
            ->where('status', JobStatus::Active)
            ->chunkById(100, function ($jobs) use ($indexName, $bar) {
                $params = ['body' => []];
                foreach ($jobs as $job) {
                    $params['body'][] = ['index' => ['_index' => $indexName, '_id' => $job->id]];
                    $params['body'][] = $job->toSearchArray();
                }
                $this->esClient->bulk($params);
                $bar->advance(count($jobs));
            });

        $bar->finish();
        $this->newLine();
    }

    private function switchAlias(string $alias, string $newIndex): void
    {
        $actions = [['add' => ['index' => $newIndex, 'alias' => $alias]]];

        // Remove alias from old indexes
        $existingIndexes = $this->esClient->indices()->getAlias(['name' => $alias])->asArray();
        foreach (array_keys($existingIndexes) as $oldIndex) {
            if ($oldIndex !== $newIndex) {
                $actions[] = ['remove' => ['index' => $oldIndex, 'alias' => $alias]];
            }
        }

        $this->esClient->indices()->updateAliases(['body' => ['actions' => $actions]]);
    }

    private function cleanupOldIndexes(string $alias, string $keepIndex): void
    {
        $pattern = $alias . '_v*';
        $indexes = $this->esClient->indices()->get(['index' => $pattern])->asArray();
        foreach (array_keys($indexes) as $index) {
            if ($index !== $keepIndex) {
                $this->esClient->indices()->delete(['index' => $index]);
                $this->line("Deleted old index: {$index}");
            }
        }
    }
}
